import {
  TableCellType,
  TableDataType,
  TableHeaderType,
  TableRowType,
} from 'components/Table/types';

const EMPTY_MERGED_CELL: TableCellType = { value: '' };

const isSubHeaderRow = (groupIndex: number, rowIndex: number): boolean =>
  groupIndex === 0 && rowIndex === 0;

export const collectLeafColumnIds = (headers: TableHeaderType[]): string[] =>
  headers.flatMap((header) => {
    if (header.children?.length) {
      return collectLeafColumnIds(header.children);
    }

    if (header.id) {
      return [header.id];
    }

    return [];
  });

export const buildColumnGroupMap = (
  headers: TableHeaderType[],
  parentTitle?: string,
): Map<string, string> => {
  const map = new Map<string, string>();

  headers.forEach((header) => {
    const groupTitle = header.children?.length ? header.title : parentTitle;

    if (header.id && groupTitle) {
      map.set(header.id, groupTitle);
    }

    if (header.children?.length) {
      buildColumnGroupMap(header.children, header.title).forEach(
        (value, key) => {
          map.set(key, value);
        },
      );
    }
  });

  return map;
};

const getMergeSpan = (cell: TableCellType): number =>
  cell.colSpan ?? cell.mergeCol ?? 0;

const getRowColumnIds = (row: TableRowType): string[] => {
  if ('isEmpty' in row) {
    return [];
  }

  return Object.keys(row).filter((key) => !key.endsWith('_config'));
};

const reanchorHiddenMerges = (
  row: TableRowType,
  leafIds: string[],
  fullLeafOrder: string[],
): TableRowType => {
  if ('isEmpty' in row) {
    return row;
  }

  const leafIdSet = new Set(leafIds);
  const adjustedRow: TableRowType = { ...row };

  fullLeafOrder.forEach((anchorId) => {
    if (leafIdSet.has(anchorId)) {
      return;
    }

    const cell = adjustedRow[anchorId];

    if (!cell || typeof cell !== 'object') {
      return;
    }

    const originalSpan = getMergeSpan(cell);

    if (originalSpan <= 1) {
      return;
    }

    const anchorIndex = fullLeafOrder.indexOf(anchorId);
    const mergeMembers = fullLeafOrder.slice(
      anchorIndex,
      anchorIndex + originalSpan,
    );
    const visibleMembers = mergeMembers.filter((columnId) =>
      leafIdSet.has(columnId),
    );

    if (visibleMembers.length === 0) {
      adjustedRow[anchorId] = EMPTY_MERGED_CELL;
      return;
    }

    const firstVisible = visibleMembers[0];

    if (visibleMembers.length === 1) {
      adjustedRow[firstVisible] = {
        ...cell,
        colSpan: undefined,
        mergeCol: undefined,
      };
    } else {
      adjustedRow[firstVisible] = {
        ...cell,
        colSpan: visibleMembers.length,
        mergeCol: visibleMembers.length,
      };

      visibleMembers.slice(1).forEach((columnId) => {
        adjustedRow[columnId] = EMPTY_MERGED_CELL;
      });
    }

    adjustedRow[anchorId] = EMPTY_MERGED_CELL;
  });

  return adjustedRow;
};

const adjustSubHeaderRow = (
  row: TableRowType,
  leafIds: string[],
  groupByColumn: Map<string, string>,
): TableRowType => {
  if ('isEmpty' in row) {
    return row;
  }

  const fullLeafOrder = getRowColumnIds(row);
  const leafIdSet = new Set(leafIds);
  const adjustedRow = reanchorHiddenMerges(row, leafIds, fullLeafOrder);

  leafIds.forEach((columnId) => {
    const cell = adjustedRow[columnId];

    if (!cell || typeof cell !== 'object') {
      adjustedRow[columnId] = cell ?? {};
    }
  });

  leafIds.forEach((columnId) => {
    const cell = adjustedRow[columnId];

    if (!cell || typeof cell !== 'object') {
      return;
    }

    const originalSpan = getMergeSpan(cell);

    if (originalSpan <= 1) {
      return;
    }

    const groupTitle = groupByColumn.get(columnId);
    const anchorIndex = fullLeafOrder.indexOf(columnId);
    const mergeMembers = fullLeafOrder
      .slice(anchorIndex, anchorIndex + originalSpan)
      .filter(
        (memberId) => !groupTitle || groupByColumn.get(memberId) === groupTitle,
      );
    const visibleMembers = mergeMembers.filter((memberId) =>
      leafIdSet.has(memberId),
    );
    const visibleSpan = visibleMembers.length;

    if (visibleSpan <= 0) {
      adjustedRow[columnId] = EMPTY_MERGED_CELL;
      return;
    }

    if (visibleSpan === 1) {
      adjustedRow[columnId] = {
        ...cell,
        colSpan: undefined,
        mergeCol: undefined,
      };
      return;
    }

    adjustedRow[columnId] = {
      ...cell,
      colSpan: visibleSpan,
      mergeCol: visibleSpan,
    };

    visibleMembers.slice(1).forEach((memberId) => {
      adjustedRow[memberId] = EMPTY_MERGED_CELL;
    });
  });

  return adjustedRow;
};

export const adjustSubHeaderColSpansForVisibleColumns = (
  data: TableDataType,
): TableDataType => {
  if (!data.header?.length || !data.rows?.length) {
    return data;
  }

  const leafIds = collectLeafColumnIds(data.header);
  const groupByColumn = buildColumnGroupMap(data.header);

  return {
    ...data,
    rows: data.rows.map((group, groupIndex) =>
      group.map((row, rowIndex) =>
        isSubHeaderRow(groupIndex, rowIndex)
          ? adjustSubHeaderRow(row, leafIds, groupByColumn)
          : row,
      ),
    ),
  };
};
